service.method:

UPDATE SBUPR
SET	 
	 SELLER_NAME_LOC	= ${SELLER_NAME_LOC}
	,IRS_NO				= ${IRS_NO}
	,ZIP_CODE			= ${ZIP_CODE}
	,ADDRESS_LOC		= ${ADDRESS_LOC}
	,PHONE_NO			= ${PHONE_NO1}
	,EMAIL				= ${EMAIL1}
	,CEO_NAME_LOC		= ${CEO_NAME_LOC}
	, DEL_FLAG       	= ${DEL_FLAG}
	,CHANGE_DATE		= ${current.DATE}
	,CHANGE_TIME		= ${current.TIME}
	,CHANGE_USER_ID		= ${session.ID}
	,FOUNDATION_DATE 	= ${FOUNDATION_DATE}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND BIZ_CODE = ${BIZ_CODE}


UPDATE SBUPI
SET  
	 USER_NAME			= ${CEO_NAME_LOC}
	,EMAIL				= ${EMAIL1}
	,PHONE_NO			= ${PHONE_NO}
	,CHANGE_DATE		= ${current.DATE}
	,CHANGE_TIME		= ${current.TIME}
	,CHANGE_USER_ID		= ${session.ID}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND BIZ_CODE = ${BIZ_CODE}
	AND USER_ID = ${BIZ_CODE}


UPDATE SUSMT
SET
 	 USER_NAME_LOC		= ${CEO_NAME_LOC}
	,EMAIL				= ${EMAIL1}
	,CHANGE_DATE		= ${current.DATE}
	,CHANGE_TIME		= ${current.TIME}
	,CHANGE_USER_ID		= ${session.ID}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${BIZ_CODE}
	AND USER_ID = ${BIZ_CODE}
